import uuid


class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}       # job_id -> record
        self._order = []      # job_ids in insertion order

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {'state': 'queued'}
                self._order.append(job_id)

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            for job_id in self._order:
                record = self._jobs[job_id]
                if record['state'] == 'queued' or (
                    record['state'] == 'running' and record['expiry'] <= now
                ):
                    record['state'] = 'running'
                    record['worker'] = worker
                    record['token'] = uuid.uuid4().hex
                    record['expiry'] = now + ttl
                    return {
                        'job_id': job_id,
                        'worker': worker,
                        'token': record['token'],
                    }
            return None

    def renew(self, lease, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            record = self._jobs.get(lease.get('job_id'))
            if record is None:
                return False
            if (
                record['state'] == 'running'
                and record['token'] == lease.get('token')
                and record['worker'] == lease.get('worker')
                and record['expiry'] > now
            ):
                record['expiry'] = now + ttl
                return True
            return False

    def complete(self, lease, now):
        with self._lock:
            record = self._jobs.get(lease.get('job_id'))
            if record is None:
                return False
            if (
                record['state'] == 'running'
                and record['token'] == lease.get('token')
                and record['worker'] == lease.get('worker')
                and record['expiry'] > now
            ):
                record['state'] = 'completed'
                return True
            return False
